namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<Course> Courses { get; set; } = [];
}

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new Department { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new Department { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Study of numbers, structures, and patterns." },
            new Department { Id = 3, Code = "ENG", Name = "English", Description = "Study of literature, writing, and language." },
            new Department { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new Department { Id = 5, Code = "HIST", Name = "History", Description = "Study of past events and human civilization." }
        ];

        _courses =
        [
            new Course { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a PhD from MIT and has published extensively on programming pedagogy.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new Course { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and competitive programming. He previously worked at Google Research.", DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true },
            new Course { Id = 3, Code = "CS 301", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transaction processing, and modern NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez has extensive industry experience designing large-scale distributed databases. She holds patents in query optimization.", DepartmentId = 1, DepartmentName = "Computer Science" },
            new Course { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning mathematics educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true },
            new Course { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications in data science and computer graphics.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Priya Patel", InstructorBio = "Dr. Patel researches applied linear algebra and its connections to machine learning. She collaborates with industry partners on real-world problems.", DepartmentId = 2, DepartmentName = "Mathematics" },
            new Course { Id = 6, Code = "MATH 301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an award-winning mathematics educator with a passion for making calculus accessible to all students.", DepartmentId = 2, DepartmentName = "Mathematics" },
            new Course { Id = 7, Code = "ENG 101", Title = "College Composition", Description = "Develop critical reading and writing skills through essay composition, research methods, and rhetorical analysis.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published author and writing instructor who believes in the power of clear, purposeful communication.", DepartmentId = 3, DepartmentName = "English", IsFeatured = true },
            new Course { Id = 8, Code = "ENG 205", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, including poetry, fiction, and nonfiction.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Rachel Green", InstructorBio = "Dr. Green specializes in 20th-century American fiction and has authored two books on the Harlem Renaissance.", DepartmentId = 3, DepartmentName = "English" },
            new Course { Id = 9, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Robert Zhang", InstructorBio = "Dr. Zhang is an experimental physicist who brings real-world research into the undergraduate classroom.", DepartmentId = 4, DepartmentName = "Physics" },
            new Course { Id = 10, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 2:00–4:00 PM", InstructorName = "Dr. Elena Novak", InstructorBio = "Dr. Novak's research focuses on photonics and electromagnetic metamaterials. She holds multiple international patents.", DepartmentId = 4, DepartmentName = "Physics" },
            new Course { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from antiquity through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an ancient history scholar who has participated in archaeological excavations across the Mediterranean.", DepartmentId = 5, DepartmentName = "History" },
            new Course { Id = 12, Code = "HIST 202", Title = "Modern European History", Description = "Political, social, and cultural transformations in Europe from the Enlightenment to the present day.", Credits = 3, Schedule = "Mon/Wed 10:00–11:15 AM", InstructorName = "Dr. Sophie Martin", InstructorBio = "Dr. Martin specializes in 19th-century European intellectual history and has published widely on nationalism and identity.", DepartmentId = 5, DepartmentName = "History" }
        ];

        foreach (var dept in _departments)
        {
            dept.Courses = _courses.Where(c => c.DepartmentId == dept.Id).ToList();
        }
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real application, this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

