+        <div class="mb-3">
+            <label for="studentId" class="form-label">Student ID</label>
+            <input type="text" id="studentId" name="Model.StudentId" value="@Model.StudentId" class="form-control" required />
+        </div>
+
+        <div class="mb-3">
+            <label for="courseId" class="form-label">Course</label>
+            <select id="courseId" name="Model.CourseId" class="form-select" required>
+                <option value="">-- Select a Course --</option>
+                @foreach (var course in courses)
+                {
+                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code - @course.Title</option>
+                }
+            </select>
+        </div>
+
+        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
+        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
+    </form>
+}
+
+@code {
+    [SupplyParameterFromForm] public EnrollmentRequest Model { get; set; } = new();
+    [SupplyParameterFromQuery] public int? CourseId { get; set; }
+
+    private List<Course> courses = [];
+    private bool submitted;
+    private string? errorMessage;
+    private string? selectedCourseTitle;
+
+    protected override void OnInitialized()
+    {
+        courses = Catalog.GetCourses();
+
+        if (CourseId.HasValue && Model.CourseId == 0)
+        {
+            Model.CourseId = CourseId.Value;
+        }
+    }
+
+    protected override void OnParametersSet()
+    {
+        if (HttpContext?.Request.Method == "POST")
+        {
+            if (string.IsNullOrWhiteSpace(Model.StudentName) ||
+                string.IsNullOrWhiteSpace(Model.StudentId) ||
+                Model.CourseId == 0)
+            {
+                errorMessage = "Please fill in all required fields.";
+                return;
+            }
+
+            var success = Catalog.SubmitEnrollmentRequest(Model);
+            if (success)
+            {
+                submitted = true;
+                selectedCourseTitle = courses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title ?? "Unknown";
+            }
+            else
+            {
+                errorMessage = "Unable to process your request. Please verify your information and try again.";
+            }
+        }
+    }
+
+    [CascadingParameter] public HttpContext? HttpContext { get; set; }
+}
+

